208	    /**
209	     * Derives the owner's age band from the birth date, measured against the registration date:
210	     * {@code 'MINOR'} when under 18, {@code 'ADULT'} for 18 to 64 inclusive, and {@code 'SENIOR'}
211	     * from 65 on. Returns {@code null} when either the birth date or the registration date is absent,
212	     * so an owner created without a birth date has no age band.
213	     */
214	    @Transient
215	    public String getAgeBand() {
216	        if (this.birthDate == null || this.registrationDate == null) {
217	            return null;
218	        }
219	        int age = Period.between(this.birthDate, this.registrationDate).getYears();
220	        if (age < 18) {
221	            return "MINOR";
222	        }
223	        return age < 65 ? "ADULT" : "SENIOR";
224	    }
