250	    /**
251	     * The number of owners belonging to this owner's household (owners sharing this owner's
252	     * household id, including this owner). Not persisted: it is a live count populated at read
253	     * time and feeds the {@code membershipPoints} calculation. Null when it has not been resolved.
254	     */
255	    public Integer getHouseholdSize() {
