263	    /**
264	     * Whether this owner was flagged a possible (soft-match) duplicate at creation: it was not a
265	     * hard duplicate, yet it shared an existing owner's lastName and postcode while carrying a
266	     * different telephone. False when no such match existed.
267	     */
268	    public Boolean getPossibleDuplicate() {
269	        return this.possibleDuplicate;
270	    }
271	
272	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
273	        this.possibleDuplicate = possibleDuplicate;
274	    }
