288	    /**
289	     * The ceiling applied to this owner's derived {@code membershipLevel}, fixed when the owner was
290	     * created: one above the maximum membershipLevel among the household members that already existed
291	     * at that time. The reported membership level is never allowed to exceed this cap. {@code null}
292	     * when the owner had no existing household member at creation, in which case no cap applies.
293	     */
294	    public Integer getMembershipLevelCap() {
295	        return this.membershipLevelCap;
296	    }
297	
298	    public void setMembershipLevelCap(Integer membershipLevelCap) {
299	        this.membershipLevelCap = membershipLevelCap;
300	    }
301	
302	    /**
303	     * Computes this owner's membership points for the given household size. Points start at 0 and
304	     * accumulate: 2 when an email address is present, 1 when the owner had no namesakes at creation
305	     * (namesakeCount is 0), 2 for a household of 3 or more members, and 3 for tenure of one or more
306	     * elapsed fiscal years (the number of 1-July fiscal-year boundaries between the registration date
307	     * and the current date). The household size is supplied by the caller (it is a live, non-persisted
308	     * count), so a {@code null} size contributes no household points.
309	     */
310	    public int membershipPoints(Integer householdSize) {
311	        int points = 0;
312	        if (this.email != null && !this.email.isBlank()) {
313	            points += 2;
314	        }
315	        if (this.namesakeCount != null && this.namesakeCount == 0) {
316	            points += 1;
317	        }
318	        if (householdSize != null && householdSize >= 3) {
319	            points += 2;
320	        }
321	        if (this.registrationDate != null
322	            && fiscalYear(LocalDate.now()) - fiscalYear(this.registrationDate) >= 1) {
323	            points += 3;
324	        }
325	        return points;
326	    }
327	
328	    /**
329	     * Derives this owner's numeric membership level for the given household size from its membership
330	     * points: 1 for 0-1 points, 2 for 2-3 points, 3 for 4-5 points, and 4 for 6 or more points. The
331	     * result is then capped at {@link #getMembershipLevelCap()} (the ceiling fixed at creation from
332	     * the household this owner joined): when a cap is present the level can never exceed it. No cap is
333	     * applied when the owner had no existing household member at creation.
334	     */
335	    public int membershipLevel(Integer householdSize) {
336	        int points = membershipPoints(householdSize);
337	        int level;
338	        if (points <= 1) {
339	            level = 1;
340	        }
341	        else if (points <= 3) {
342	            level = 2;
343	        }
344	        else if (points <= 5) {
345	            level = 3;
346	        }
347	        else {
348	            level = 4;
349	        }
350	        if (this.membershipLevelCap != null && level > this.membershipLevelCap) {
351	            level = this.membershipLevelCap;
352	        }
353	        return level;
354	    }
355	
356	    /**
357	     * Whether this owner has been soft-deleted. A newly created owner is not deleted; a
358	     * {@code DELETE /api/owners/{id}} flags it deleted while retaining the row. Deleted owners are
359	     * ignored by the create endpoint's duplicate and identity checks.
360	     */
361	    public boolean isDeleted() {
362	        return this.deleted;
363	    }
364	
365	    public void setDeleted(boolean deleted) {
366	        this.deleted = deleted;
367	    }
368	
369	    /**
370	     * The owner's derived identity key, used as the single basis for duplicate detection: the
371	     * lower-case hex SHA-256 digest over {@code normalizedTelephone + '|' + lowerEmail + '|' +
372	     * soundex(lastName)}, where the telephone and email components are empty when absent. Two
373	     * owners are duplicates only when their whole identity keys are equal, so any single differing
374	     * component (telephone, email or the surname's soundex) yields distinct keys and is allowed.
375	     * Derived from persisted fields, so it is not itself a persistent column.
376	     */
377	    @Transient
378	    public String getIdentityKey() {
379	        String normalizedTelephone = this.telephone == null ? "" : this.telephone;
380	        String lowerEmail = this.email == null ? "" : this.email.toLowerCase();
381	        String seed = normalizedTelephone + "|" + lowerEmail + "|" + soundex(getLastName());
382	        return sha256Hex(seed);
383	    }
384	
385	    /**
386	     * Returns the full lower-case hex SHA-256 digest of the UTF-8 bytes of {@code seed} (64 hex
387	     * characters).
388	     */
389	    private static String sha256Hex(String seed) {
390	        try {
391	            MessageDigest digest = MessageDigest.getInstance("SHA-256");
392	            byte[] hash = digest.digest(seed.getBytes(StandardCharsets.UTF_8));
393	            StringBuilder sb = new StringBuilder(hash.length * 2);
394	            for (byte b : hash) {
395	                sb.append(String.format("%02x", b));
396	            }
397	            return sb.toString();
398	        }
399	        catch (NoSuchAlgorithmException e) {
400	            throw new IllegalStateException("SHA-256 not available", e);
401	        }
402	    }
403	
404	    /**
405	     * Computes the American Soundex code for a name: the retained first letter followed by three
406	     * digits derived from the remaining consonants (b,f,p,v-&gt;1; c,g,j,k,q,s,x,z-&gt;2; d,t-&gt;3;
407	     * l-&gt;4; m,n-&gt;5; r-&gt;6), with adjacent equal codes collapsed, h and w ignored (so they do
408	     * not separate equal codes) and vowels acting as separators, right-padded with zeros to length
409	     * four. Returns an empty string when the value is null or holds no letters, so surnames that
410	     * sound alike share a code.
411	     */
412	    public static String soundex(String value) {
413	        if (value == null) {
414	            return "";
415	        }
416	        String letters = value.toUpperCase().replaceAll("[^A-Z]", "");
417	        if (letters.isEmpty()) {
418	            return "";
419	        }
420	        StringBuilder code = new StringBuilder();
421	        code.append(letters.charAt(0));
422	        char previous = soundexDigit(letters.charAt(0));
423	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
424	            char c = letters.charAt(i);
425	            if (c == 'H' || c == 'W') {
426	                continue;
427	            }
428	            char digit = soundexDigit(c);
429	            if (digit != '0' && digit != previous) {
430	                code.append(digit);
431	            }
432	            previous = digit;
433	        }
434	        while (code.length() < 4) {
435	            code.append('0');
436	        }
437	        return code.toString();
438	    }
439	
440	    /** Maps a letter to its Soundex digit, or {@code '0'} for vowels, y, h and w. */
441	    private static char soundexDigit(char c) {
442	        return switch (c) {
443	            case 'B', 'F', 'P', 'V' -> '1';
444	            case 'C', 'G', 'J', 'K', 'Q', 'S', 'X', 'Z' -> '2';
445	            case 'D', 'T' -> '3';
446	            case 'L' -> '4';
447	            case 'M', 'N' -> '5';
448	            case 'R' -> '6';
449	            default -> '0';
450	        };
451	    }
452	
453	    /**
454	     * Establishes the effective registration date at persist time, so the create-time default
455	     * applies to any persistence path.
456	     */
457	    @PrePersist
458	    protected void defaultRegistrationDate() {
459	        resolveRegistrationDate();
460	    }
461	
462	    /**
463	     * Resolves this owner's effective registration date and stores it: the supplied value is used, or
464	     * the server's current date when none was supplied, and the result is rolled forward onto a
465	     * business day (a Saturday, Sunday or public holiday rolls forward to the next business day).
466	     * Returns the resolved date.
467	     * Idempotent, so it is safe to call from both the create flow and the persist hook.
468	     */
469	    public LocalDate resolveRegistrationDate() {
470	        LocalDate effective = this.registrationDate == null ? LocalDate.now() : this.registrationDate;
471	        this.registrationDate = toBusinessDay(effective);
472	        return this.registrationDate;
473	    }
474	
475	    /**
476	     * Derives the fiscal year that a date falls in, where each fiscal year starts on 1 July and is
477	     * identified by the calendar year in which it ends: a date from July onwards belongs to the
478	     * fiscal year ending in the following calendar year (e.g. 2 July 2026 gives 2027), while a date
479	     * from January to June belongs to the fiscal year ending in its own calendar year. Returns
480	     * {@code null} when the date is absent.
481	     */
482	    public static Integer fiscalYear(LocalDate date) {
483	        if (date == null) {
484	            return null;
485	        }
486	        return date.getMonthValue() >= Month.JULY.getValue() ? date.getYear() + 1 : date.getYear();
487	    }
488	
489	    /**
490	     * Rolls a registration date forward onto a business day: a Saturday, Sunday or listed public
491	     * holiday is advanced to the next non-holiday weekday, while any other weekday (and {@code null})
492	     * is returned unchanged. Applying this to a date that is already a business day is a no-op, so it
493	     * is safe to call more than once.
494	     */
495	    public static LocalDate toBusinessDay(LocalDate date) {
496	        if (date == null) {
497	            return null;
498	        }
499	        LocalDate result = date;
500	        while (isWeekend(result) || PUBLIC_HOLIDAYS.contains(result)) {
501	            result = result.plusDays(1);
502	        }
503	        return result;
504	    }
505	
506	    private static boolean isWeekend(LocalDate date) {
507	        return switch (date.getDayOfWeek()) {
508	            case SATURDAY, SUNDAY -> true;
509	            default -> false;
510	        };
511	    }
512	
513	    protected Set<Pet> getPetsInternal() {
514	        if (this.pets == null) {
515	            this.pets = new HashSet<>();
516	        }
517	        return this.pets;
518	    }
519	
520	    protected void setPetsInternal(Set<Pet> pets) {
521	        this.pets = pets;
522	    }
523	
524	    public List<Pet> getPets() {
525	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
526	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
527	        return Collections.unmodifiableList(sortedPets);
528	    }
529	
530	    public void setPets(List<Pet> pets) {
531	        this.pets = new HashSet<>(pets);
532	    }
533	
534	    public void addPet(Pet pet) {
535	        getPetsInternal().add(pet);
536	        pet.setOwner(this);
537	    }
538	
539	    /**
540	     * Return the Pet with the given name, or null if none found for this Owner.
541	     *
542	     * @param name to test
543	     * @return true if pet name is already in use
544	     */
545	    public Pet getPet(String name) {
546	        return getPet(name, false);
547	    }
548	
549	    /**
550	     * Return the Pet with the given name, or null if none found for this Owner.
551	     *
552	     * @param name to test
553	     * @return true if pet name is already in use
554	     */
555	    public Pet getPet(String name, boolean ignoreNew) {
556	        name = name.toLowerCase();
557	        for (Pet pet : getPetsInternal()) {
558	            if (!ignoreNew || !pet.isNew()) {
559	                String compName = pet.getName();
560	                compName = compName.toLowerCase();
561	                if (compName.equals(name)) {
562	                    return pet;
563	                }
564	            }
565	        }
566	        return null;
567	    }
568	
569	    public Pet getPet(Integer petId) {
570	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
571	    }
572	
573	    @Override
574	    public String toString() {
575	        return new ToStringCreator(this)
576	
577	            .append("id", this.getId())
578	            .append("new", this.isNew())
579	            .append("lastName", this.getLastName())
580	            .append("firstName", this.getFirstName())
581	            .append("address", this.address)
582	            .append("city", this.city)
583	            .append("telephone", this.telephone)
584	            .toString();
585	    }
586	}
